import unittest
from pathlib import Path

import guard

ME = ("Rohan Balu", "117021386+rohanbalu05@users.noreply.github.com")
OK = guard.DEFAULT_AUTHORS
FIXTURE = (Path(__file__).parent / "fixtures" / "bad_commit_message.txt").read_text()


def run(title="[TY6-02] x", body="", commits=(("c" * 40, *ME, "[TY6-02] x"),), diff=""):
    return guard.check(title, body, list(commits), diff, OK)


class Guard(unittest.TestCase):
    def test_clean_pr_passes(self):
        self.assertEqual(run(), [])

    def test_fixture_commit_message_is_rejected(self):
        problems = run(commits=[("d" * 40, *ME, FIXTURE)])
        self.assertEqual(len(problems), 1)
        self.assertIn("message contains attribution", problems[0])

    def test_title_and_body_are_checked(self):
        self.assertTrue(run(title="Generated with Claude Code"))
        self.assertTrue(run(body="see https://claude.ai/code/session_1 for details"))

    def test_environment_footer_is_ignored_in_body(self):
        footer = "What\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_\n"
        self.assertEqual(run(body=footer), [])

    def test_unknown_author_rejected(self):
        problems = run(commits=[("e" * 40, "Someone", "someone@example.com", "msg")])
        self.assertIn("not allowed", problems[0])

    def test_noreply_email_maps_to_login(self):
        self.assertTrue(guard.author_ok("x", "5+rohanbalu05@users.noreply.github.com", OK))

    def test_diff_flags_added_lines_outside_exempt_files(self):
        diff = "+++ b/src/a.py\n+x = 'Claude-Session'\n+++ b/CLAUDE.md\n+Claude-Session\n"
        problems = run(diff=diff)
        self.assertEqual(problems, ["src/a.py contains attribution text"])

    def test_removed_lines_are_ignored(self):
        self.assertEqual(run(diff="+++ b/a.py\n-Claude-Session\n"), [])


if __name__ == "__main__":
    unittest.main()
